pub fn from_column_index(column_index: ColumnIndex, spec: &ChainSpec) -> Self {
    column_index
        .safe_rem(spec.data_column_sidecar_subnet_count)
        .expect(
            "data_column_sidecar_subnet_count should never be zero if this function is called",
        )
        .into()
}

